csharp.divide_polyline:
Pts = new List<Point3d>();
if (P == null || P.Count < 2 || P.Count > 100000 || N < 1 || N > 10000) return;
double[] lengths = new double[P.Count - 1];
double total = 0.0;
for (int j = 0; j < lengths.Length; j++)
{
  if (!P[j].IsValid || !P[j + 1].IsValid) return;
  lengths[j] = P[j].DistanceTo(P[j + 1]);
  total += lengths[j];
}
if (total <= 0.0 || double.IsInfinity(total) || double.IsNaN(total)) return;
List<Point3d> result = new List<Point3d>();
double passed = 0.0;
int edge = 0;
for (int i = 0; i <= N; i++)
{
  if (i == 0) { result.Add(P[0]); continue; }
  if (i == N) { result.Add(P[P.Count - 1]); continue; }
  double target = total * i / N;
  while (edge < lengths.Length - 1 && passed + lengths[edge] < target)
  { passed += lengths[edge]; edge++; }
  while (edge < lengths.Length - 1 && lengths[edge] == 0.0) edge++;
  if (lengths[edge] == 0.0) return;
  double fraction = (target - passed) / lengths[edge];
  result.Add(P[edge] + (P[edge + 1] - P[edge]) * fraction);
}
Pts = result;

csharp.bounds_points:
Min = null;
Max = null;
if (P == null || P.Count < 1 || P.Count > 100000) return;
double minX = double.PositiveInfinity, minY = double.PositiveInfinity, minZ = double.PositiveInfinity;
double maxX = double.NegativeInfinity, maxY = double.NegativeInfinity, maxZ = double.NegativeInfinity;
foreach (Point3d point in P)
{
  if (!point.IsValid) return;
  minX = Math.Min(minX, point.X); minY = Math.Min(minY, point.Y); minZ = Math.Min(minZ, point.Z);
  maxX = Math.Max(maxX, point.X); maxY = Math.Max(maxY, point.Y); maxZ = Math.Max(maxZ, point.Z);
}
Min = new Point3d(minX, minY, minZ);
Max = new Point3d(maxX, maxY, maxZ);

brep_tree:
var tree = new DataTree<Curve>();
C = tree;

// A disconnected optional Brep is an idle state, not an error.
if (B == null) return;
if (!B.IsValid || F < 0 || F >= B.Faces.Count)
{
  Print("Select a valid Brep and face index.");
  return;
}
if (N < 1 || N > 10000)
{
  Print("N must be between 1 and 10000.");
  return;
}

BrepFace face = B.Faces[F];
Interval uDomain = face.Domain(0);
if (!uDomain.IsValid)
{
  Print("The selected face has no valid U domain.");
  return;
}

for (int i = 0; i < N; i++)
{
  GH_Path path = new GH_Path(i);
  tree.EnsurePath(path);
  double fraction = (i + 1.0) / (N + 1.0);
  double u = uDomain.T0 + fraction * (uDomain.T1 - uDomain.T0);
  Curve[] pieces = face.TrimAwareIsoCurve(0, u);
  if (pieces == null) continue;
  foreach (Curve piece in pieces)
    if (piece != null && piece.IsValid) tree.Add(piece, path);
}
